<?php
namespace App\Http\Controllers;
use App\Models\SiteSetting;use Illuminate\Http\Request;use Illuminate\Http\RedirectResponse;use Illuminate\Support\Facades\Crypt;use Illuminate\Support\Facades\Http;use Illuminate\View\View;
class AdminFonnteController extends Controller {
 public function edit(): View {$row=SiteSetting::where('key','fonnte_token')->first();return view('admin.settings.fonnte',['configured'=>(bool)$row,'endpoint'=>SiteSetting::where('key','fonnte_endpoint')->value('value') ?: config('services.fonnte.endpoint')]);}
 public function update(Request $r): RedirectResponse {$d=$r->validate(['token'=>['nullable','string','max:500'],'endpoint'=>['required','url','max:255']]);if(filled($d['token']??null))SiteSetting::updateOrCreate(['key'=>'fonnte_token'],['value'=>Crypt::encryptString($d['token'])]);SiteSetting::updateOrCreate(['key'=>'fonnte_endpoint'],['value'=>$d['endpoint']]);return back()->with('success','Pengaturan Fonnte disimpan. Token lama tetap digunakan jika kolom token dikosongkan.');}
 public function test(Request $r): RedirectResponse {$d=$r->validate(['target'=>'required|string|min:8|max:25']);$token=$this->token();if(!$token)return back()->withErrors(['token'=>'Token Fonnte belum diatur.']);$target=preg_replace('/\D+/','',$d['target']);if(str_starts_with($target,'0'))$target='62'.substr($target,1);$endpoint=SiteSetting::where('key','fonnte_endpoint')->value('value') ?: config('services.fonnte.endpoint');try{$res=Http::asForm()->withHeaders(['Authorization'=>$token])->timeout(15)->post($endpoint,['target'=>$target,'message'=>'Tes koneksi WhatsApp HYPESOLE berhasil.']);if($res->successful() && $res->json('status')===true)return back()->with('success','Pesan tes berhasil diterima Fonnte.');}catch(\Throwable $e){}return back()->withErrors(['test'=>'Tes gagal. Periksa token, endpoint, dan nomor tujuan.']);}
 private function token(): ?string {$v=SiteSetting::where('key','fonnte_token')->value('value');if(!$v)return config('services.fonnte.token');try{return Crypt::decryptString($v);}catch(\Throwable $e){return null;}}
}
